from __future__ import annotations

import datetime as dt

import ds.data
import pytest
from ds.data.raw import smashtube
from ds.data.raw.smashtube import SITE_CHARACTER, VideoQuery, parse_videos, search_params, search_videos


def _video(video_id: str, title: str, date: str, players: list[str]) -> str:
    tags = "".join(f'<a href="result?player1={p}#result">#{p}</a>' for p in players)
    return f"""
    <div class="rsg">
      <div class="result-youtube">
        <img class="v-modal" data-video="{video_id}" data-title="{title}"
             src="https://img.youtube.com/vi/{video_id}/mqdefault.jpg" alt="YouTube Thumbnail">
      </div>
      <div class="result-vtitle">
        <div class="Vtitle v-modal" data-video="{video_id}" data-title="{title}" data-fulltitle="{title}">
          <p class="result-title">{title}</p>
        </div>
        <div class="Pdate"><p>{date} </p></div>
        <div class="date_tag_box"><div class="playerTag">{tags}</div></div>
      </div>
    </div>"""


def _page(count_line: str, *videos: str) -> str:
    message = f'<div class="resultmsg"><div class="resultmsg-content">{count_line}<br>match videos</div></div>'
    return f"""<html><body>
      <div class="rsg"><img data-video="NOT_A_RESULT"></div>
      <div class="result" id="result"><div class="rslt-box">{message if count_line else ""}
        <div class="result-content">{"".join(videos)}</div>
      </div></div></body></html>"""


def test_parse_videos() -> None:
    html = _page(
        "500+ videos found (2 / 50)",
        _video("57I2f-kKk10", "Neo (Corrin) vs Sparg0 (Cloud) - TOP 8", "2026-11-09", ["Neo", "Sparg0"]),
        _video("INNeqo5cKoI", "Some clip", "not a date", []),
    )
    total, page, pages, videos = parse_videos(html)
    assert (total, page, pages) == ("500+", 2, 50)
    assert [v.video_id for v in videos] == ["57I2f-kKk10", "INNeqo5cKoI"]  # only inside #result
    first = videos[0]
    assert first.title == "Neo (Corrin) vs Sparg0 (Cloud) - TOP 8"
    assert first.date == dt.date(2026, 11, 9)
    assert first.players == ["Neo", "Sparg0"]
    assert first.url == "https://www.youtube.com/watch?v=57I2f-kKk10"
    assert first.thumbnail_url == "https://img.youtube.com/vi/57I2f-kKk10/mqdefault.jpg"
    assert first.embed_url.endswith("/embed/57I2f-kKk10")
    assert videos[1].date is None
    assert {"url", "thumbnail_url"} <= first.model_dump().keys()


def test_parse_empty_result() -> None:
    assert parse_videos(_page("")) == ("0", 1, 1, [])
    assert parse_videos(_page("0 videos found (1 / 0)")) == ("0", 1, 1, [])


def test_parse_rejects_changed_layout() -> None:
    with pytest.raises(ValueError, match="#result"):
        parse_videos("<html><body>nothing</body></html>")


def test_every_char_id_maps_to_a_site_character() -> None:
    char_ids = set(ds.data.init_db().sql("select id from char")["id"])
    assert char_ids == set(SITE_CHARACTER)


def test_search_params() -> None:
    query = VideoQuery(player_1="Sparg0", char_2="little_mac", region="NA")
    assert search_params(query) == {
        "player1": "Sparg0",
        "character1": "",
        "player2": "",
        "character2": "リトル・マック",
        "free_word": "",
        "region": "NA",
    }
    assert search_params(query, page=3)["page_id"] == "3"


@pytest.mark.parametrize(
    "query",
    [VideoQuery(region="Mars"), VideoQuery(search_term="x" * 21), VideoQuery(char_1="not_a_char")],
)
def test_search_params_rejects_bad_input(query: VideoQuery) -> None:
    with pytest.raises(ValueError):  # noqa: PT011  # three different messages, one per case
        search_params(query)


def test_search_videos(monkeypatch: pytest.MonkeyPatch) -> None:
    seen: dict[str, str] = {}

    def fake_fetch(params: dict[str, str]) -> tuple[str, str]:
        seen.update(params)
        return "https://smash-tube.com/en/result?x", _page(
            "1 videos found (1 / 1)", _video("abc", "T", "2026-01-02", [])
        )

    monkeypatch.setattr(smashtube, "fetch_result_page", fake_fetch)
    result = search_videos(player_1=" Sparg0 ", char_1="cloud")
    assert seen["player1"] == "Sparg0"
    assert seen["character1"] == "クラウド"
    assert (result.total, result.page, result.pages, len(result.videos)) == ("1", 1, 1, 1)
    assert result.query.char_1 == "cloud"
    with pytest.raises(ValueError, match="at least one"):
        search_videos()
